mapper.select:
SELECT supplier.ID, supplier.COMPANY_NAME, supplier.SOURCE, supplier.CREATE_TIME, supplier.STATUS, supplier.BUSINESS_SCOPE, supplier.IS_BLACKLIST, supplier.SN, supplier.MODEL_ID, supplier.PROCESS_INSTANCE_ID, relation.BUSINESSADMIN_NAME, relation.BUSINESSADMIN_PHONE FROM BP_SUPPLIER supplier left join (select SUPPLIER_ID from BP_BUSINESS_SCOPE where DELETE_FLAG='NOT_DELETE'
and SUPPLIER_ID in
#{item}
) business on supplier.id = business.SUPPLIER_ID left join BP_RELATION relation on relation.SUPPLIER_ID = supplier.id ${ew.customSqlSegment}
